<?php
namespace App\Livewire\Accounting;
use App\Models\GlAccountMapping; use App\Services\GlExportService; use Livewire\Component;
class Mapping extends Component { public array $codes=[]; public array $names=[]; public function mount():void{foreach(GlExportService::REQUIRED as $key){$m=GlAccountMapping::where('key',$key)->first();$this->codes[$key]=$m?->account_code??'';$this->names[$key]=$m?->account_name??ucwords(str_replace('_',' ',$key));}} public function save():void{$this->authorize('manage-hr');foreach(GlExportService::REQUIRED as $key){$code=trim((string)($this->codes[$key]??''));$name=trim((string)($this->names[$key]??''));if($code===''||$name===''){$this->addError('mapping','Every GL mapping requires an account code and name.');return;}GlAccountMapping::updateOrCreate(['key'=>$key],['account_code'=>$code,'account_name'=>$name]);}session()->flash('success','GL mappings saved.');} public function render(){return view('livewire.accounting.mapping',['keys'=>GlExportService::REQUIRED]);} }
